sys_script_include.script:
var PlacementDriveEligibility = Class.create();
PlacementDriveEligibility.prototype = Object.extendsObject(
    global.AbstractAjaxProcessor,
    {

        calculateEligibility: function() {

            // =====================================================
            // GET VALUES FROM PLACEMENT DRIVE FORM
            // =====================================================

            var eligibleBranches =
                this.getParameter('sysparm_branches');

            var minimumCGPA =
                this.getParameter('sysparm_cgpa');

            var maxBacklogs =
                this.getParameter('sysparm_backlogs');

            var mandatorySkills =
                this.getParameter('sysparm_skills');


            // =====================================================
            // CHECK REQUIRED VALUES
            // =====================================================

            if (!eligibleBranches ||
                !minimumCGPA ||
                maxBacklogs === null ||
                maxBacklogs === undefined ||
                maxBacklogs === '' ||
                !mandatorySkills) {

                return '0';
            }


            // =====================================================
            // CONVERT NUMERIC VALUES
            // =====================================================

            var cgpa = parseFloat(minimumCGPA);
            var backlogLimit = parseInt(maxBacklogs, 10);


            if (isNaN(cgpa) || isNaN(backlogLimit)) {
                return '0';
            }


            // =====================================================
            // GET SELECTED BRANCH SYS_IDS
            // =====================================================

            var branchIds =
                eligibleBranches.split(',');

            var cleanBranchIds = [];

            for (var i = 0; i < branchIds.length; i++) {

                var branchId =
                    branchIds[i].trim();

                if (branchId) {
                    cleanBranchIds.push(branchId);
                }
            }


            // =====================================================
            // GET MANDATORY SKILL SYS_IDS
            // =====================================================

            var skillIds =
                mandatorySkills.split(',');

            var cleanSkillIds = [];

            for (var j = 0; j < skillIds.length; j++) {

                var skillId =
                    skillIds[j].trim();

                if (skillId) {
                    cleanSkillIds.push(skillId);
                }
            }


            if (cleanBranchIds.length === 0 ||
                cleanSkillIds.length === 0) {

                return '0';
            }


            // =====================================================
            // GET BRANCH DISPLAY VALUES
            //
            // Placement Drive:
            // eligible_branches = reference list
            //
            // Student:
            // branch = choice field
            // =====================================================

            var allowedBranchNames =
                this.getAllowedBranchNames(
                    cleanBranchIds
                );


            if (allowedBranchNames.length === 0) {
                return '0';
            }


            // =====================================================
            // GET STUDENTS
            // =====================================================

            var studentGR =
                new GlideRecord(
                    'x_snc_college_pl_0_student'
                );


            // =====================================================
            // CGPA CONDITION
            // =====================================================

            studentGR.addQuery(
                'cgpa',
                '>=',
                cgpa
            );


            // =====================================================
            // BACKLOG CONDITION
            // =====================================================

            studentGR.addQuery(
                'backlogs',
                '<=',
                backlogLimit
            );


            studentGR.query();


            // =====================================================
            // COUNT ELIGIBLE STUDENTS
            // =====================================================

            var eligibleCount = 0;


            while (studentGR.next()) {

                // =================================================
                // CHECK BRANCH
                // =================================================

                var studentBranchValue =
                    studentGR.getValue('branch');

                var studentBranchDisplay =
                    studentGR.getDisplayValue('branch');


                var branchMatched = false;


                for (var b = 0;
                     b < allowedBranchNames.length;
                     b++) {

                    if (
                        studentBranchValue ==
                            allowedBranchNames[b] ||

                        studentBranchDisplay ==
                            allowedBranchNames[b]
                    ) {

                        branchMatched = true;
                        break;
                    }
                }


                // Student branch doesn't match
                if (!branchMatched) {
                    continue;
                }


                // =================================================
                // CHECK MANDATORY SKILLS
                // =================================================

                var studentSkills =
                    studentGR.getValue('skills') || '';


                var studentSkillIds =
                    studentSkills.split(',');


                var hasAllSkills = true;


                for (var s = 0;
                     s < cleanSkillIds.length;
                     s++) {

                    var requiredSkillId =
                        cleanSkillIds[s];

                    var hasSkill = false;


                    for (var ss = 0;
                         ss < studentSkillIds.length;
                         ss++) {

                        if (
                            studentSkillIds[ss].trim() ==
                            requiredSkillId
                        ) {

                            hasSkill = true;
                            break;
                        }
                    }


                    // Student is missing a mandatory skill
                    if (!hasSkill) {

                        hasAllSkills = false;
                        break;
                    }
                }


                // =================================================
                // STUDENT PASSED ALL CONDITIONS
                // =================================================

                if (hasAllSkills) {
                    eligibleCount++;
                }
            }


            // =====================================================
            // RETURN COUNT TO CLIENT SCRIPT
            // =====================================================

            return eligibleCount.toString();
        },


        // =========================================================
        // GET DISPLAY NAMES OF SELECTED BRANCH REFERENCES
        // =========================================================

        getAllowedBranchNames: function(branchIds) {

            var branchNames = [];


            // -----------------------------------------------------
            // Read the reference table of eligible_branches
            // -----------------------------------------------------

            var dictionary =
                new GlideRecord('sys_dictionary');


            dictionary.addQuery(
                'name',
                'x_snc_college_pl_0_placement_drive'
            );

            dictionary.addQuery(
                'element',
                'eligible_branches'
            );

            dictionary.setLimit(1);
            dictionary.query();


            if (!dictionary.next()) {
                return branchNames;
            }


            var referenceTable =
                dictionary.getValue('reference');


            if (!referenceTable) {
                return branchNames;
            }


            // -----------------------------------------------------
            // Get selected branch records
            // -----------------------------------------------------

            var branchGR =
                new GlideRecord(referenceTable);


            for (var i = 0;
                 i < branchIds.length;
                 i++) {

                if (branchGR.get(branchIds[i])) {

                    branchNames.push(
                        branchGR.getDisplayValue()
                    );
                }
            }


            return branchNames;
        },


        type: 'PlacementDriveEligibility'
    }
);
